INSERT INTO `space_versions` (`version`, `title`, `summary`, `created_at`) VALUES
('v84', '豆包切换模型改为新开官网对话生效', '查清了豆包模型切换只有第一次生效、两个豆包都切换只有一个生效的原因：选择包每次发送都按各智能体自己的选型正确发出了，但豆包的模型是在官网对话创建时定下的，在原对话里续发改不了——生效的那次恰好是切换后新建的对话。现在改为：豆包智能体的模型或推理强度真的变了时（设置面板和聊天框工具栏两处保存都算），清掉它名下的官网对话续接，下一条回复新开一个官网对话、由创建请求带上新选型，之后再回到固定续发；重复保存同一选型、只改联网搜索不动任何对话。两个豆包各清各的，互不影响。界面说明已同步改成这个行为。', 1795196400000);
